var t=`Rumor`;var n=`dice`;var s=`2d6`;var l=[{roll:2,result:`A large object fell from the sky and is now hidden in a heavily guarded facility on the outskirts of the Town.`},{roll:3,result:`The most important people in the Town are actually shape-shifting humanoids.`},{roll:4,result:`Bright objects were seen crossing the sky.`},{roll:5,result:`Mutilated animals were found on the outskirts of the Town; all of them bore bloodless excisions.`},{roll:6,result:`Strange and complex patterns have appeared in the fields on the outskirts of the Town.`},{roll:7,result:`Strange sounds and lights were witnessed in the Abandoned Mill.`},{roll:8,result:`The birds in the Town are actually robots that the government uses to keep an eye on everyone.`},{roll:9,result:`Government officials are using a secret facility somewhere in the Town to conduct covert research.`},{roll:10,result:`A convoy of military trucks was seen driving through the Town.`},{roll:11,result:`Men dressed in black suits who claim to be government agents were seen around the Town looking for an inconspicuous citizen.`},{roll:12,result:`Small humanoids with bulbous heads and green skin have been spotted around the Town.`}];var r={label:t,type:n,dice:`2d6`,entries:l};export{r as default,s as dice,l as entries,t as label,n as type};